#include <stdio.h>
#include <stdlib.h>

long long count_leq(int *a, int n, long long S) {
    if (S < 0) return 0;

    long long total = 0;
    long long sum = 0;
    int left = 0;

    for (int right = 0; right < n; ++right) {
        sum += a[right];

        while (sum > S) {
            sum -= a[left];
            ++left;
        }

        total += (long long)(right - left + 1);
    }

    return total;
}

int main() {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *a = (int *)malloc(sizeof(int) * N);
    if (a == NULL) return 0;

    for (int i = 0; i < N; ++i) {
        scanf("%d", &a[i]);
    }

    long long ans = count_leq(a, N, K) - count_leq(a, N, (long long)K - 1);

    printf("%lld\n", ans);

    free(a);
    return 0;
}
